55	export const sanitizeTag = (tag, options = {}) => {
56	  const typeofTag = typeof tag;
57	  if (!tag || !['string', 'object'].includes(typeofTag)) {
58	    return null;
59	  }
60	
61	  let usableTagString = typeof tag == 'string' ? tag : 'name' in tag ? tag.name : '';
62	
63	  let sanitized = usableTagString.trim();
64	
65	  // BRU format only supports alphanumeric, hyphens, and underscores in tags
66	  // The BRU grammar defines listitem as: (alnum | "_" | "-")+
67	  // Spaces are NOT allowed, so we replace them with underscores
68	
69	  // Replace spaces with underscores first
70	  sanitized = sanitized.replace(/\s+/g, '_');
71	
72	  // Replace any character that's NOT alphanumeric, hyphen, or underscore with underscore
73	  sanitized = sanitized.replace(/[^\p{L}\p{N}\-_]/gu, '_');
74	
75	  // Collapse multiple consecutive underscores into one
76	  sanitized = sanitized.replace(/_+/g, '_');
77	
78	  // Remove leading characters that aren't alphanumeric
79	  sanitized = sanitized.replace(/^[^\p{L}\p{N}]+/gu, '');
80	
81	  // Remove trailing characters that aren't alphanumeric
82	  sanitized = sanitized.replace(/[^\p{L}\p{N}]+$/gu, '');
83	
84	  // Return null if the result is empty
85	  return sanitized || null;
86	};
