 200,\n            _postman_previewlanguage: 'json',\n            header: [\n              {\n                key: 'Content-Type',\n                value: 'application/json',\n                name: 'Content-Type',\n                description: '',\n                type: 'text'\n              },\n              {\n                key: 'x-powered-by',\n                value: 'Express'\n              }\n            ],\n            cookie: [],\n            body: '{\\n    \"ping\": \"pong\"\\n}'\n          },\n          {\n            name: 'Error Response',\n            originalRequest: {\n              method: 'GET',\n              header: [\n                {\n                  key: 'Content-Type',\n                  value: 'application/json',\n                  type: 'text'\n                }\n              ],\n              body: {\n                mode: 'raw',\n                raw: '{\\n    \"ping\": \"pong\"\\n}',\n                options: {\n                  raw: {\n                    language: 'json'\n                  }\n                }\n              },\n              url: {\n                raw: 'https://testbench-sanity.usebruno.com/ping',\n                protocol: 'https',\n                host: ['testbench-sanity', 'usebruno', 'com'],\n                path: ['ping']\n              }\n            },\n            status: 'Internal Server Error',\n            code: 500,\n            _postman_previewlanguage: 'json',\n            header: [\n              {\n                key: 'Content-Type',\n                value: 'application/json',\n                name: 'Content-Type',\n                description: '',\n                type: 'text'\n              }\n            ],\n            cookie: [],\n            body: '{\\n    \"error\": \"Internal Server Error\"\\n}'\n          }\n        ]\n      }\n    ]\n  };\n\n  test('should convert Postman collection with examples to Bruno format', async () => {\n    const brunoCollection = await postmanToBruno(postmanCo