+{"version":3,"names":["_globals","require","_openapiToBruno","_interopRequireDefault","e","__esModule","default","describe","it","spec","result","openApiToBruno","getItem","items","find","i","name","putItem","expect","request","params","toEqual","arrayContaining","objectContaining","type","enabled","search","queryParams","filter","p","toHaveLength","toBe","pathParams","listItems","limitParams","description","getResource","headers","trackingHeader","h","toBeDefined","qParam","value","limitParam","getUser","userIdParam","filterParam","openapi","info","title","version","servers","url","paths","get","summary","operationId","parameters","in","schema","properties","page","example","size","sort","required","responses","pageParam","sizeParam","sortParam","author","genre","listBooks","titleParam","authorParam","genreParam","enum","format","formatParam","examples","statusParam","minimum","maximum"],"sources":["openapi-path-parameters.spec.js"],"sourcesContent":["import { describe, it, expect } from '@jest/globals';\nimport openApiToBruno from '../../../src/openapi/openapi-to-bruno';\n\ndescribe('openapi path-item level parameters', () => {\n  it('should apply path-item parameters to all operations when no operation params exist', () => {\n    const spec = `\nopenapi: '3.0.0'\ninfo:\n  title: 'Path Params API'\n  version: '1.0.0'\nservers:\n  - url: 'https://api.example.com'\npaths:\n  /items/{itemId}:\n    parameters:\n      - name: itemId\n        in: path\n        required: true\n        schema:\n          type: string\n        description: 'The item ID'\n    get:\n      summary: 'Get item'\n      operationId: 'getItem'\n      responses:\n        '200':\n          description: 'OK'\n    put:\n      summary: 'Update item'\n      operationId: 'updateItem'\n      responses:\n        '200':\n          description: 'OK'\n`;\n    const result = openApiToBruno(spec);\n\n    // Both GET and PUT should have the itemId path parameter\n    const getItem = result.items.find((i) => i.name === 'Get item');\n    const putItem = result.items.find((i) => i.name === 'Update item');\n\n    expect(getItem.request.params).toEqual(\n      expect.arrayContaining([expect.objectContaining({ name: 'itemId', type: 'path', enabled: true })])\n    );\n    expect(putItem.request.params).toEqual(\n      expect.arrayContaining([expect.objectContaining({ name: 'itemId', type: 'path', enabled: true })])\n    );\n  });\n\n  it('should preserve operation-only parameters unchanged', () => {\n    const spec = `\nopenapi: '3.0.0'\ninfo:\n  title: 'Op Only Params API'\n  version: '1.0.0'\nservers:\n  - url: 'https://api.example.com'\npaths:\n  /search:\n    get:\n      summary: 'Search'\n      operationId: 'search'\n      parameters:\n        - name: q\n          in: query\n          required: true\n          schema:\n            type: string\n          description: 'Search query'\n      responses:\n        '200':\n          description: 'OK'\n`;\n    const result = openApiToBruno(spec);\n    const search = result.items.find((i) => i.name === 'Search');\n    const queryParams = search.request.params.filter((p) => p.type === 'query');\n    expect(queryParams).toHaveLength(1);\n    expect(queryParams[0].name).toBe('q');\n  });\n\n  it('should merge path-item and operation params with no overlap', () => {\n    const spec = `\nopenapi: '3.0.0'\ninfo:\n  title: 'Merge No Overlap API'\n  version: '1.0.0'\nservers:\n  - url: 'https://api.example.com'\npaths:\n  /items/{itemId}:\n    parameters:\n      - name: itemId\n        in: path\n        required: true\n        schema:\n          type: string\n    get:\n      summary: 'Get item'\n      operationId: 'getItem'\n      parameters:\n        - name: fields\n          in: query\n          required: false\n          schema:\n            type: string\n          description: 'Fields to include'\n      responses:\n        '200':\n          description: 'OK'\n`;\n    const result = openApiToBruno(spec);\n    const getItem = result.items.find((i) => i.name === 'Get item');\n\n    // Should have both the path param from path-item and the query param from operation\n    const pathParams = getItem.request.params.filter((p) => p.type === 'path');\n    const queryParams = getItem.request.params.filter((p) => p.type === 'query');\n    expect(pathParams).toHaveLength(1);\n    expect(pathParams[0].name).toBe('itemId');\n    expect(queryParams).toHaveLength(1);\n    expect(queryParams[0].name).toBe('fields');\n  });\n\n  it('should let operation param override path-item param with same name and in', () => {\n    const spec = `\nopenapi: '3.0.0'\ninfo:\n  title: 'Override API'\n  version: '1.0.0'\nservers:\n  - url: 'https://api.example.com'\npaths:\n  /items:\n    parameters:\n      - name: limit\n        in: query\n        required: false\n        schema:\n          type: integer\n        description: 'Default limit from path-item'\n    get:\n      summary: 'List items'\n      operationId: 'listItems'\n      parameters:\n        - name: limit\n          in: query\n          required: true\n          schema:\n            type: integer\n            maximum: 50\n          description: 'Override limit for list operation'\n      responses:\n        '200':\n          description: 'OK'\n`;\n    const result = openApiToBruno(spec);\n    const listItems = result.items.find((i) => i.name === 'List items');\n\n    // Should have exactly one 'limit' query param -- the operation-level one\n    const limitParams = listItems.request.params.filter((p) => p.name === 'limit');\n    expect(limitParams).toHaveLength(1);\n    expect(limitParams[0].description).toBe('Override limit for list operation');\n    expect(limitParams[0].enabled).toBe(true); // required=true from operation\n  });\n\n  it('should handle path-item params with different in values (query, path, header)', () => {\n    const spec = `\nopenapi: '3.0.0'\ninfo:\n  title: 'Mixed In Values API'\n  version: '1.0.0'\nservers:\n  - url: 'https://api.example.com'\npa