+{"version":3,"names":["_brunoToPostman","require","describe","it","url","params","name","value","type","result","transformUrl","expect","toEqual","raw","protocol","host","path","query","variable","key","input","expected","sanitizeUrl","toBe","simpleCollection","items","request","method","headers","brunoToPostman","item","header","enabled","disabled","body","toBeUndefined","mode","formUrlEncoded","urlencoded","multipartForm","formdata","originalConsoleError","console","error","jest","fn","docs","description","auth","bearer","token","basic","username","password","undefined","apikey","src","contentType","protocolProfileBehavior","disableBodyPruning","json","script","req","res","events","event","toHaveLength","toMatchObject","listen","exec","folder","root","nestedRequest","makeRequest","seq","makeFolder","collection","names","map","i","parent","nestedNames"],"sources":["bruno-to-postman.spec.js"],"sourcesContent":["import { sanitizeUrl, transformUrl, brunoToPostman } from '../../src/postman/bruno-to-postman';\n\ndescribe('transformUrl', () => {\n  it('should handle basic URL with path variables', () => {\n    const url = 'https://example.com/{{username}}/api/resource/:id';\n    const params = [\n      { name: 'id', value: '123', type: 'path' }\n    ];\n\n    const result = transformUrl(url, params);\n\n    expect(result).toEqual({\n      raw: 'https://example.com/{{username}}/api/resource/:id',\n      protocol: 'https',\n      host: ['example', 'com'],\n      path: ['{{username}}', 'api', 'resource', ':id'],\n      query: [],\n      variable: [\n        { key: 'id', value: '123' }\n      ]\n    });\n  });\n\n  it('should handle URL with query parameters', () => {\n    const url = 'https://example.com/api/resource?limit=10&offset=20';\n    const params = [\n      { name: 'limit', value: '10', type: 'query' },\n      { name: 'offset', value: '20', type: 'query' }\n    ];\n\n    const result = transformUrl(url, params);\n\n    expect(result).toEqual({\n      raw: 'https://example.com/api/resource?limit=10&offset=20',\n      protocol: 'https',\n      host: ['example', 'com'],\n      path: ['api', 'resource'],\n      query: [\n        { key: 'limit', value: '10' },\n        { key: 'offset', value: '20' }\n      ],\n      variable: []\n    });\n  });\n\n  it('should handle URL without protocol', () => {\n    const url = 'example.com/api/resource';\n    const params = [];\n\n    const result = transformUrl(url, params);\n\n    expect(result).toEqual({\n      raw: 'example.com/api/resource',\n      protocol: '',\n      host: ['example', 'com'],\n      path: ['api', 'resource'],\n      query: [],\n      variable: []\n    });\n  });\n});\n\ndescribe('sanitizeUrl', () => {\n  it('should replace backslashes with slashes', () => {\n    const input = 'http:\\\\\\\\example.com\\\\path\\\\to\\\\file';\n    const expected = 'http://example.com/path/to/file';\n    expect(sanitizeUrl(input)).toBe(expected);\n  });\n\n  it('should collapse multiple slashes into a single slash', () => {\n    const input = 'http://example.com//path///to////file';\n    const expected = 'http://example.com/path/to/file';\n    expect(sanitizeUrl(input)).toBe(expected);\n  });\n\n  it('should handle URLs with mixed slashes', () => {\n    const input = 'http:\\\\example.com//path\\\\to//file';\n    const expected = 'http://example.com/path/to/file';\n    expect(sanitizeUrl(input)).toBe(expected);\n  });\n});\n\ndescribe('brunoToPostman null checks and fallbacks', () => {\n  it('should handle null or undefined headers', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            headers: null\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.header).toEqual([]);\n  });\n\n  it('should handle null or undefined items in headers', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            headers: [\n              { name: null, value: 'test-value', enabled: true },\n              { name: 'Content-Type', value: null, enabled: true }\n            ]\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.header).toEqual([\n      { key: '', value: 'test-value', disabled: false, type: 'default' },\n      { key: 'Content-Type', value: '', disabled: false, type: 'default' }\n    ]);\n  });\n\n  it('should handle null or undefined body', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            body: null\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    // Should not have body property since we're checking for body before adding it\n    expect(result.item[0].request.body).toBeUndefined();\n  });\n\n  it('should handle null or undefined body mode', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            body: {}\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    // Should use default raw mode for undefined body mode\n    expect(result.item[0].request.body).toEqual({\n      mode: 'raw',\n      raw: ''\n    });\n  });\n\n  it('should handle null or undefined formUrlEncoded array', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'POST',\n            url: 'https://example.com',\n            body: {\n              mode: 'formUrlEncoded',\n              formUrlEncoded: null\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.body).toEqual({\n      mode: 'urlencoded',\n      urlencoded: []\n    });\n  });\n\n  it('should handle null or undefined multipartForm array', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'POST',\n            url: 'https://example.com',\n            body: {\n              mode: 'multipartForm',\n              multipartForm: null\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.body).toEqual({\n      mode: 'formdata',\n      formdata: []\n    });\n  });\n\n  it('should handle null or undefined items in form data', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'POST',\n            url: 'https://example.com',\n            body: {\n              mode: 'formUrlEncoded',\n              formUrlEncoded: [\n                { name: null, value: 'test-value', enabled: true },\n                { name: 'field', value: null, enabled: true }\n              ]\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.body.urlencoded).toEqual([\n      { key: '', value: 'test-value', disabled: false, type: 'default' },\n      { key: 'field', value: '', disabled: false, type: 'default' }\n    ]);\n  });\n\n  it('should handle null or undefined method', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            url: 'https://example.com',\n            method: null\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.method).toBe('GET');\n  });\n\n  it('should handle null or undefined url', () => {\n    // Mock console.error to prevent it from logging during test\n    const originalConsoleError = console.error;\n    console.error = jest.fn();\n\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: null\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.url.raw).toBe('');\n  });\n\n  it('should handle null or undefined params', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            params: null\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.url.variable).toEqual([]);\n  });\n\n  it('should handle null or undefined docs', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            docs: null\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.description).toBe('');\n  });\n\n  it('should handle null or undefined folder name', () => {\n    const simpleCollection = {\n      items: [\n        {\n          type: 'folder',\n          name: null,\n          items: []\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].name).toBe('Untitled Folder');\n  });\n\n  it('should handle null or undefined request name', () => {\n    const simpleCollection = {\n      items: [\n        {\n          type: 'http-request',\n          name: null,\n          request: {\n            method: 'GET',\n            url: 'https://example.com'\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].name).toBe('Untitled Request');\n  });\n\n  it('should handle null or undefined folder items', () => {\n    const simpleCollection = {\n      items: [\n        {\n          type: 'folder',\n          name: 'Test Folder',\n          items: null\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].item).toEqual([]);\n  });\n\n  it('should handle null or undefined auth object', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            auth: null\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.auth).toEqual({ type: 'noauth' });\n  });\n\n  it('should handle missing token in bearer auth', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            auth: {\n              mode: 'bearer',\n              bearer: { token: null }\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.auth).toEqual({\n      type: 'bearer',\n      bearer: {\n        key: 'token',\n        value: '',\n        type: 'string'\n      }\n    });\n  });\n\n  it('should handle missing username/password in basic auth', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            auth: {\n              mode: 'basic',\n              basic: { username: null, password: undefined }\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.auth).toEqual({\n      type: 'basic',\n      basic: [\n        {\n          key: 'password',\n          value: '',\n          type: 'string'\n        },\n        {\n          key: 'username',\n          value: '',\n          type: 'string'\n        }\n      ]\n    });\n  });\n\n  it('should handle missing key/value in apikey auth', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'GET',\n            url: 'https://example.com',\n            auth: {\n              mode: 'apikey',\n              apikey: { key: null, value: undefined }\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.auth).toEqual({\n      type: 'apikey',\n      apikey: [\n        {\n          key: 'key',\n          value: '',\n          type: 'string'\n        },\n        {\n          key: 'value',\n          value: '',\n          type: 'string'\n        }\n      ]\n    });\n  });\n});\n\ndescribe('brunoToPostman multipartForm handling', () => {\n  it('should export file type with type: file and src field', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'POST',\n            url: 'https://example.com',\n            body: {\n              mode: 'multipartForm',\n              multipartForm: [\n                {\n                  name: 'myFile',\n                  value: ['/path/to/file1.txt', '/path/to/file2.txt'],\n                  type: 'file',\n                  enabled: true\n                }\n              ]\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.body).toEqual({\n      mode: 'formdata',\n      formdata: [\n        {\n          key: 'myFile',\n          src: ['/path/to/file1.txt', '/path/to/file2.txt'],\n          disabled: false,\n          type: 'file'\n        }\n      ]\n    });\n  });\n\n  it('should export text type with type: text and value field', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'POST',\n            url: 'https://example.com',\n            body: {\n              mode: 'multipartForm',\n              multipartForm: [\n                {\n                  name: 'myField',\n                  value: 'some text value',\n                  type: 'text',\n                  enabled: true\n                }\n              ]\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.body).toEqual({\n      mode: 'formdata',\n      formdata: [\n        {\n          key: 'myField',\n          value: 'some text value',\n          disabled: false,\n          type: 'text'\n        }\n      ]\n    });\n  });\n\n  it('should export contentType when specified', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'POST',\n            url: 'https://example.com',\n            body: {\n              mode: 'multipartForm',\n              multipartForm: [\n                {\n                  name: 'myFile',\n                  value: ['/path/to/file.json'],\n                  type: 'file',\n                  contentType: 'application/json',\n                  enabled: true\n                }\n              ]\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.body).toEqual({\n      mode: 'formdata',\n      formdata: [\n        {\n          key: 'myFile',\n          src: '/path/to/file.json',\n          disabled: false,\n          type: 'file',\n          contentType: 'application/json'\n        }\n      ]\n    });\n  });\n\n  it('should handle mixed file and text fields', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'POST',\n            url: 'https://example.com',\n            body: {\n              mode: 'multipartForm',\n              multipartForm: [\n                {\n                  name: 'textField',\n                  value: 'hello',\n                  type: 'text',\n                  enabled: true\n                },\n                {\n                  name: 'fileField',\n                  value: ['/path/to/file.txt'],\n                  type: 'file',\n                  enabled: false\n                }\n              ]\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.body).toEqual({\n      mode: 'formdata',\n      formdata: [\n        {\n          key: 'textField',\n          value: 'hello',\n          disabled: false,\n          type: 'text'\n        },\n        {\n          key: 'fileField',\n          src: '/path/to/file.txt',\n          disabled: true,\n          type: 'file'\n        }\n      ]\n    });\n  });\n\n  it('should handle file type with string value (not array)', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'POST',\n            url: 'https://example.com',\n            body: {\n              mode: 'multipartForm',\n              multipartForm: [\n                {\n                  name: 'myFile',\n                  value: '/single/file/path.txt',\n                  type: 'file',\n                  enabled: true\n                }\n              ]\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.body.formdata[0]).toEqual({\n      key: 'myFile',\n      src: '/single/file/path.txt',\n      disabled: false,\n      type: 'file'\n    });\n  });\n\n  it('should handle file type with empty value', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'Test Request',\n          type: 'http-request',\n          request: {\n            method: 'POST',\n            url: 'https://example.com',\n            body: {\n              mode: 'multipartForm',\n              multipartForm: [\n                {\n                  name: 'myFile',\n                  value: '',\n                  type: 'file',\n                  enabled: true\n                }\n              ]\n            }\n          }\n        }\n      ]\n    };\n\n    const result = brunoToPostman(simpleCollection);\n    expect(result.item[0].request.body.formdata[0]).toEqual({\n      key: 'myFile',\n      src: null,\n      disabled: false,\n      type: 'file'\n    });\n  });\n});\n\ndescribe('brunoToPostman protocolProfileBehavior handling', () => {\n  it('should add disableBodyPruning for GET requests with body', () => {\n    const simpleCollection = {\n      items: [\n        {\n          name: 'GET with body',\n          type: