onseCode.code;\n        const name = responseCode.name;\n        console.log(code, name);\n      `;\n      const result = translateCode(input);\n      expect(result).toContain('const code = res.getStatus();');\n      expect(result).toContain('const name = res.statusText;');\n    });\n  });\n\n  describe('postman.getResponseHeader translations', () => {\n    test('should translate postman.getResponseHeader', () => {\n      const input = 'postman.getResponseHeader(\"Content-Type\");';\n      const result = translateCode(input);\n      expect(result).toBe('res.getHeader(\"Content-Type\");');\n    });\n\n    test('should translate postman.getResponseHeader in assignment', () => {\n      const input = 'const contentType = postman.getResponseHeader(\"Content-Type\");';\n      const result = translateCode(input);\n      expect(result).toBe('const contentType = res.getHeader(\"Content-Type\");');\n    });\n\n    test('should translate postman.getResponseHeader with variable argument', () => {\n      const input = 'const headerName = \"Authorization\"; const value = postman.getResponseHeader(headerName);';\n      const result = translateCode(input);\n      expect(result).toContain('res.getHeader(headerName)');\n    });\n  });\n});\n"],"mappings":";;AAAA,IAAAA,yBAAA,GAAAC,sBAAA,CAAAC,OAAA;AAA8E,SAAAD,uBAAAE,CAAA,WAAAA,CAAA,IAAAA,CAAA,CAAAC,UAAA,GAAAD,CAAA,KAAAE,OAAA,EAAAF,CAAA;AAE9EG,QAAQ,CAAC,gCAAgC,EAAE,MAAM;EAC/CA,QAAQ,CAAC,uCAAuC,EAAE,MAAM;IACtDC,IAAI,CAAC,4DAA4D,EAAE,MAAM;MACvE,MAAMC,KAAK,GAAG;AACpB;AACA,CAAC;MAEK,MAAMC,MAAM,GAAG,IAAAC,iCAAa,EAACF,KAAK,CAAC;MACnC,MAAMG,QAAQ,GAAG;AACvB;AACA,CAAC;MAEKC,MAAM,CAACH,MAAM,CAAC,CAACI,OAAO,CAACF,QAAQ,CAAC;IAClC,CAAC,CAAC;IAEFJ,IAAI,CAAC,+DAA+D,EAAE,MAAM;MAC1E,MAAMC,KAAK,GAAG;AACpB;AACA;AACA,OAAO;MAED,MAAMC,MAAM,GAAG,IAAAC,iCAAa,EAACF,KAAK,CAAC;MAEnCI,MAAM,CAACH,MAAM,CAAC,CAACK,SAAS,CAAC,kBAAkB,CAAC;MAC5CF,MAAM,CAACH,MAAM,CAAC,CAACM,GAAG,CAACD,SAAS,CAAC,iBAAiB,CAAC;IACjD,CAAC,CAAC;IAEFP,IAAI,CAAC,4DAA4D,EAAE,MAAM;MACvE,MAAMC,KAAK