ion() {');\n    expect(translatedCode).toContain('const data = pm.response.json();');\n    expect(translatedCode).toContain('if (!data.id) {');\n    expect(translatedCode).toContain('pm.expect.fail(\"Missing ID field\");');\n    expect(translatedCode).toContain('if (data.status !== \\'active\\' && data.status !== \\'pending\\') {');\n    expect(translatedCode).toContain('pm.expect.fail(\"Invalid status: \" + data.status);');\n    expect(translatedCode).toContain('pm.expect(data.name).to.be.a(\\'string\\');');\n  });\n});\n"],"mappings":";;AAAA,IAAAA,yBAAA,GAAAC,sBAAA,CAAAC,OAAA;AAAmF,SAAAD,uBAAAE,CAAA,WAAAA,CAAA,IAAAA,CAAA,CAAAC,UAAA,GAAAD,CAAA,KAAAE,OAAA,EAAAF,CAAA;AAEnFG,QAAQ,CAAC,gDAAgD,EAAE,MAAM;EAC/D;EACAC,EAAE,CAAC,sCAAsC,EAAE,MAAM;IAC/C,MAAMC,IAAI,GAAG,oFAAoF;IACjG,MAAMC,cAAc,GAAG,IAAAC,iCAAqB,EAACF,IAAI,CAAC;IAClDG,MAAM,CAACF,cAAc,CAAC,CAACG,IAAI,CAAC,2FAA2F,CAAC;EAC1H,CAAC,CAAC;EAEFL,EAAE,CAAC,0CAA0C,EAAE,MAAM;IACnD,MAAMC,IAAI,GAAG,sCAAsC;IACnD,MAAMC,cAAc,GAAG,IAAAC,iCAAqB,EAACF,IAAI,CAAC;IAClDG,MAAM,CAACF,cAAc,CAAC,CAACG,IAAI,CAAC,yCAAyC,CAAC;EACxE,CAAC,CAAC;EAEFL,EAAE,CAAC,oDAAoD,EAAE,MAAM;IAC7D,MAAMC,IAAI,GAAG,+CAA+C;IAC5D,MAAMC,cAAc,GAAG,IAAAC,iCAAqB,EAACF,IAAI,CAAC;IAClDG,MAAM,CAACF,cAAc,CAAC,CAACG,IAAI,CAAC,kDAAkD,CAAC;EACjF,CAAC,CAAC;;EAEF;EACAL,EAAE,CAAC,yCAAyC,EAAE,MAAM;IAClD,MAAMC,IAAI,GAAG;AACjB;AACA;AACA;AACA,IAAI;IACA,MAAMC,cAAc,GAAG,IAAAC,iCAAqB,EAACF,IAAI,CAAC;IAClDG,MAAM,CAACF,cAAc,CAAC,CAACG,IAAI,CAAC;AAChC;AACA;AACA;AACA,IAAI,CAAC;EACH,CAAC,CAAC;;EAEF;EACAL,EAAE,CAAC,4CAA4C,EAAE,MAAM;IACrD,MAAMC,IAAI,GAAG;AACjB;AACA;AACA;AACA,CAAC;IACG,MAAMC,cAAc,GAAG,IAAAC,iCAAqB,EAACF,IAAI,CAAC;IAElDG,MAAM,CAACF,cAAc,CAAC,CAACI,SAAS,CAAC,uCAAuC,CAAC;IACzEF,MAAM,CAACF,cAAc,CAAC,CAACI,SAAS,CAAC,4CAA4C,CAAC;EAChF,CAAC,CAAC;EAEFN,EAAE,CAAC,wDAAwD,EAAE,MAAM;IACjE,MAAMC,IAAI,GAAG;AACjB;AACA;AACA;AACA;AACA;AACA;AACA,CAAC;IACG,MAAMC,cAAc,GAAG,IAAAC,iCAAqB,EAACF,IAAI,CAAC;IAElDG,MAAM,CAACF,cAAc,CAAC,CAACI,SAAS,CAAC,oDAAoD,CAAC;IACtFF,MAAM,CAACF,cAAc,CAAC,CAACI,SA