subfolders[0].name).toBe('{subId}');\n    expect(subfolders[0].type).toBe('folder');\n    expect(subfolders[0].items).toHaveLength(1);\n    expect(subfolders[0].items[0].name).toBe('Get by ID and sub ID');\n    expect(subfolders[0].items[0].request.url).toBe('{{baseUrl}}/:id/:subId');\n  });\n\n  it('should handle tag based grouping', () => {\n    const result = openApiToBruno(openApiSpec, { groupBy: 'tags' });\n\n    // With tags grouping, requests without tags should be ungrouped\n    expect(result.items).toHaveLength(2);\n\n    // Both should be individual requests (not in folders)\n    result.items.forEach((item) => {\n      expect(item.type).toBe('http-request');\n    });\n\n    // Check request names\n    const requestNames = result.items.map((req) => req.name);\n    expect(requestNames).toContain('Get by ID');\n    expect(requestNames).toContain('Get by ID and sub ID');\n\n    // Check request URLs\n    const urls = result.items.map((req) => req.request.url);\n    expect(urls).toContain('{{baseUrl}}/:id');\n    expect(urls).toContain('{{baseUrl}}/:id/:subId');\n  });\n});\n"],"mappings":"AAAA,SAASA,QAAQ,EAAEC,EAAE,EAAEC,MAAM,QAAQ,eAAe;AACpD,OAAOC,cAAc,MAAM,uCAAuC;AAElE,MAAMC,WAAW,GAAG;EAClBC,OAAO,EAAE,OAAO;EAChBC,IAAI,EAAE;IAAEC,KAAK,EAAE,eAAe;IAAEC,OAAO,EAAE;EAAQ,CAAC;EAClDC,OAAO,EAAE,CAAC;IAAEC,GAAG,EAAE;EAA0B,CAAC,CAAC;EAC7CC,KAAK,EAAE;IACL,OAAO,EAAE;MACPC,GAAG,EAAE;QACHC,OAAO,EAAE,WAAW;QACpBC,WAAW,EAAE,SAAS;QACtBC,SAAS,EAAE;UAAE,GAAG,EAAE;YAAEC,WAAW,EAAE;UAAK;QAAE;MAC1C;IACF,CAAC;IACD,eAAe,EAAE;MACfJ,GAAG,EAAE;QACHC,OAAO,EAAE,sBAAsB;QAC/BC,WAAW,EAAE,iBAAiB;QAC9BC,SAAS,EAAE;UAAE,GAAG,EAAE;YAAEC,WAAW,EAAE;UAAK;QAAE;MAC1C;IACF;EACF;AACF,CAAC;AAEDhB,QAAQ,CAAC,yBAAyB,EAAE,MAAM;EACxCC,EAAE,CAAC,mCAAmC,EAAE,MAAM;IAC5C,MAAMgB,MAAM,GAAGd,cAAc,CAACC,WAAW,EAAE;MAAEc,OAAO,EAAE;IAAO,CAAC,CAAC;;IAE/D;IACAhB,MAAM,CAACe,MAAM,CAACE,KAAK,CAAC,CAACC,YAAY,CAAC,CAAC,CAAC;IAEpC,MAAMC,MAAM,GAAGJ,MAAM,CAACE,KAAK,CAAC,CAAC,CAAC;IAC9BjB,MAAM,CAACmB,MAAM,CAACC,IAAI,CAAC,CAACC,IAAI,