+    const request = findRequestByName(result.items, 'Get users');
+    expect(request).toBeDefined();
+    expect(request.tags).toEqual([]);
+  });
+  it('should handle missing tags property', () => {
+    const spec = {
+      swagger: '2.0',
+      info: {
+        title: 'Tags API',
+        version: '1.0'
+      },
+      host: 'api.example.com',
+      paths: {
+        '/users': {
+          get: {
+            summary: 'Get users',
+            responses: {
+              200: {
+                description: 'Success'
+              }
+            }
+          }
+        }
