+        title: 'Tags API',
+        version: '1.0'
+      },
+      host: 'api.example.com',
+      paths: {
+        '/users': {
+          get: {
+            summary: 'Get users',
+            tags: ['User Management'],
+            responses: {
+              200: {
+                description: 'Success'
+              }
+            }
+          }
+        }
+      }
+    };
+    const result = swagger2ToBruno(spec);
+
+    // The folder name should be sanitized (first tag)
+    const folder = findFolderByName(result.items, 'User_Management');
+    expect(folder).toBeDefined();
+  });
+  it('should handle UTF-8 characters in tags', () => {
+    const spec = {
+      swagger: '2.0',
+      info: {
+        title: 'Tags API',
+        version: '1.0'
+      },
+      host: 'api.example.com',
+      paths: {
+        '/users': {
+          get: {
+            summary: 'Get users',
+            tags: ['Ünïcödé', '日本語'],
+            responses: {
+              200: {
+                description: 'Success'
+              }
+            }
+          }
+        }
+      }
+    };
+
+    // Should not throw
+    expect(() => swagger2ToBruno(spec)).not.toThrow();
+    const result = swagger2ToBruno(spec);
+    expect(result).toBeDefined();
