+  /test:
+    get:
+      summary: 'Test'
+      responses:
+        '200':
+          description: 'OK'
+servers:
+  - url: '{protocol}://{host}/v1'
+    description: 'Production'
+    variables:
+      protocol:
+        default: 'https'
+      host:
+        default: 'api.prod.com'
+  - url: 'https://staging.example.com/v1'
+    description: 'Staging'
