+    const spec = `
+openapi: 3.0.3
+info:
+  title: Digest API
+  version: '1.0'
+components:
+  securitySchemes:
+    DigestAuth:
+      type: http
+      scheme: digest
+paths:
+  /secure:
+    get:
+      security:
+        - DigestAuth: []
+      responses:
+        '200': { description: OK }
+servers:
+  - url: https://example.com
+`;
+    const collection = openApiToBruno(spec);
+    const req = collection.items[0];
+    expect(req.request.auth.mode).toBe('digest');
+    expect(req.request.auth.digest).toEqual({
+      username: '{{username}}',
+      password: '{{password}}'
+    });
+  });
